template <int K>
__device__ __forceinline__ void packed_cholesky_step_64(
    float (&row_values)[64],
    float* tile,
    float* inverse,
    int group,
    int lane,
    bool active
) {
    float value = 0.0f;
    if (active && lane >= K) {
        value = row_values[K];
        #pragma unroll
        for (int j = 0; j < K; ++j) {
            value = fmaf(
                -row_values[j],
                tile[packed_cholesky64_column(j) + K - j],
                value
            );
        }
    }

    if (active && lane == K) {
        const float diagonal = sqrtf(fmaxf(value, 1.0e-30f));
        row_values[K] = diagonal;
        tile[packed_cholesky64_column(K)] = diagonal;
        inverse[group] = 1.0f / diagonal;
    }
    __syncthreads();

    if (active && lane > K) {
        value *= inverse[group];
        row_values[K] = value;
        tile[packed_cholesky64_column(K) + lane - K] = value;
    }
    __syncthreads();

    if constexpr (K + 1 < 64) {
        packed_cholesky_step_64<K + 1>(
            row_values, tile, inverse, group, lane, active
        );
    }
}

